package com.flippingfriend.companion;
import com.flippingfriend.model.RiskAppetite;
/** Pure fail-closed binding of expected-profit evidence to CandidateFactory worst-loss inputs. */
final class BuyReplacementWorstLossInputContextComposer {
 BuyReplacementWorstLossInputContext compose(BuyReplacementExpectedProfitEvaluationSet s,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty())return null;RiskAppetite appetite=RiskAppetite.forName(s.getAppetiteName());double loss=appetite.getLossCutPct();if(!appetite.getName().equalsIgnoreCase(s.getAppetiteName())||!Double.isFinite(loss)||loss<=0)return null;for(BuyReplacementExpectedProfitEvaluation e:s.getEvaluations())if(!valid(e,s))return null;return new BuyReplacementWorstLossInputContext(s,loss,at);}
 private static boolean valid(BuyReplacementExpectedProfitEvaluation e,BuyReplacementExpectedProfitEvaluationSet s){return e!=null&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&e.getBuyPrice()>0&&e.getSellPrice()>0&&e.getTotalCost()==(long)e.getBuyPrice()*e.getExactRemainderQuantity()&&e.getTotalNetMargin()==e.getNetMarginPerItem()*e.getExactRemainderQuantity()&&e.getTotalUnwindLoss()>=0&&Double.isFinite(e.getExpectedProfit())&&Double.compare(e.getCompletedProbability(),e.getBuyProbability()*e.getSellProbability())==0&&Double.compare(e.getStrandedProbability(),e.getBuyProbability()*(1-e.getSellProbability()))==0&&Double.compare(e.getExpectedProfit(),e.getCompletedProbability()*e.getTotalNetMargin()-e.getStrandedProbability()*e.getTotalUnwindLoss())==0&&Double.isFinite(e.getExpectedSlotHours())&&e.getExpectedSlotHours()>=1.0/60.0;}
}
